import {distance,hit} from './enemies.js';
export const ITEMS={meteor:{name:'Meteor strike',cost:8,icon:'☄',desc:'180 true damage in a large area. Click a target.'},militia:{name:'Summon militia',cost:5,icon:'⚑',desc:'Three blocking allies for 30 seconds. Click the road.'},heal:{name:'Heal flask',cost:3,icon:'✚',desc:'Restore hero and soldiers to full health.'},gold:{name:'Gold charm',cost:5,icon:'◈',desc:'Gain 100 gold immediately.'}};
export function useItem(g,key,p){const item=ITEMS[key];if(g.outcome||g.paused||g.save.gems<item.cost){g.notify('Not enough gems, or battle paused');return false;}if(!p&&['meteor','militia'].includes(key)){g.targeting=key;g.notify('Choose a target on the battlefield');return true;}g.save.gems-=item.cost;if(key==='meteor'){for(const e of g.enemies)if(distance(e,p)<60)hit(g,e,180,'true');g.effects.push({type:'ring',...p,r:60,color:'#ffb668',life:1});g.shake=8;g.audio.play('blast');}if(key==='militia')for(let i=0;i<3;i++)g.soldiers.push({militia:true,x:p.x+i*6-6,y:p.y,hp:110,maxHP:110,armor:.15,attack:0,life:30,sprite:98});if(key==='heal'){g.hero.hp=g.hero.maxHP;g.hero.respawn=0;for(const s of g.soldiers){s.hp=s.maxHP;s.respawn=0;}}if(key==='gold')g.gold+=100;g.persist();g.notify(`${item.name} used`);g.targeting=null;return true;}
